using D=std::array<long double,3>;
D add(D a,D b){for(size_t k=0;k<3;++k)a[k]+=b[k];return a;}D scale(D a,long double q){for(auto&x:a)x*=q;return a;}D cross(D a,D b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}D unit(D a){const auto d=std::sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]);for(auto&x:a)x/=d;return a;}Vec3 vec(D a){return {float(a[0]),float(a[1]),float(a[2])};}D vec(Vec3 a){return {a.x,a.y,a.z};}
